package org.sleepwell.app;
import org.junit.Test;import static org.junit.Assert.*;
public final class PictureHoldTest {
    PictureSignature reference=PictureSignature.from(PictureSignatureTest.scene(41),128,128,0),different=PictureSignature.from(PictureSignatureTest.scene(93),128,128,0);
    @Test public void threeFreshStableFramesOverDeclaredSpanAreRequired(){PictureHold hold=new PictureHold(reference);assertFalse(hold.frame(reference,1000,1000));assertFalse(hold.frame(reference,1200,1200));assertTrue(hold.frame(reference,1400,1400));hold.reset();assertEquals(0,hold.progress());assertFalse(hold.frame(reference,1500,1500));}
    @Test public void missingDifferentStaleDuplicateFutureAndLongGapResetHold(){for(int failure=0;failure<6;failure++){PictureHold hold=new PictureHold(reference);hold.frame(reference,1000,1000);hold.frame(reference,1200,1200);if(failure==0)assertFalse(hold.frame(null,1400,1400));if(failure==1)assertFalse(hold.frame(different,1400,1400));if(failure==2)assertFalse(hold.frame(reference,1400,2201));if(failure==3)assertFalse(hold.frame(reference,1200,1400));if(failure==4)assertFalse(hold.frame(reference,1500,1400));if(failure==5)assertFalse(hold.frame(reference,1601,1601));assertFalse(hold.frame(reference,1800,1800));}}
    @Test public void sensorTimestampMustMapToOneSupportedMonotonicClock(){assertEquals(1950,PictureHold.captured(1950000000L,2000,1980));assertEquals(2970,PictureHold.captured(1950000000L,3000,1980));assertEquals(-1,PictureHold.captured(1,3000,4000));assertEquals(-1,PictureHold.captured(-1,3000,4000));}
    @Test public void proofRequiresSameRequestReferenceCurrentUnitAndFreshSingleUse(){String key=reference.key();PictureProof proof=new PictureProof("run",2,"nonce",key,1000);assertFalse(proof.consume("run",2,"wrong",key,1400,1500,"run",2,key,true,false));assertFalse(proof.consume("run",2,"nonce",key,999,1500,"run",2,key,true,false));assertTrue(proof.consume("run",2,"nonce",key,1400,1500,"run",2,key,true,false));assertFalse(proof.consume("run",2,"nonce",key,1400,1500,"run",2,key,true,false));PictureProof stale=new PictureProof("run",2,"nonce",key,1000);assertFalse(stale.consume("run",2,"nonce",key,1400,11401,"run",2,key,true,false));assertFalse(stale.consume("run",2,"nonce",key,1400,1500,"other",2,key,true,false));assertFalse(stale.consume("run",2,"nonce",key,1400,1500,"run",2,key,true,false));}
    @Test public void mathFallbackIsOwnedButNeverRequiresCameraSuccess(){PictureProof proof=new PictureProof("run",2,"nonce",reference.key(),1000);assertTrue(proof.consume("run",2,"nonce",reference.key(),0,2000,"run",2,reference.key(),true,true));assertFalse(proof.consume("run",2,"nonce",reference.key(),0,2000,"run",2,reference.key(),true,true));}
}
